svg.script:
(function () {
  const svg = document.documentElement;
  const field = document.getElementById('field');
  const NS = "http://www.w3.org/2000/svg";

  const tubes = [];
  const spacing = 28;
  let mouse = { x: 0, y: 0, active: false };
  let smoothMouse = { x: 0, y: 0 };
  let t = 0;
  let running = true;

  function toSvgPoint(clientX, clientY) {
    const pt = svg.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    const m = svg.getScreenCTM();
    if (!m) return { x: 0, y: 0 };
    const local = pt.matrixTransform(m.inverse());
    return { x: local.x, y: local.y };
  }

  function onPointerMove(e) {
    const p = toSvgPoint(e.clientX, e.clientY);
    mouse.x = p.x;
    mouse.y = p.y;
    mouse.active = true;
  }

  function onPointerLeave() {
    mouse.active = false;
  }

  svg.addEventListener('pointermove', onPointerMove);
  svg.addEventListener('pointerenter', onPointerMove);
  svg.addEventListener('pointerleave', onPointerLeave);

  for (let x = -266; x <= 266; x += spacing) {
    for (let y = -266; y <= 266; y += spacing) {
      const g = document.createElementNS(NS, 'g');
      const path = document.createElementNS(NS, 'path');
      path.setAttribute('class', 'tube');
      g.appendChild(path);
      field.appendChild(g);

      const r = Math.hypot(x, y);
      const depth = Math.min(1, r / 360);

      tubes.push({
        x: x,
        y: y,
        g: g,
        path: path,
        r: r,
        depth: depth,
        phase: r * 0.018 + x * 0.006 - y * 0.004,
        h: 18 + (1 - depth) * 9,
        scale: 0.92 + (1 - depth) * 0.55,
        opacity: 0.18 + (1 - depth) * 0.62,
        stroke: 1.0 + (1 - depth) * 1.9
      });
    }
  }

  function lerp(a, b, k) { return a + (b - a) * k; }

  function updateTube(tube, breath) {
    const x = tube.x;
    const y = tube.y;
    const depth = tube.depth;
    const phase = tube.phase;

    const baseAngle = Math.sin(t * 0.42 + phase) * (4.5 + (1 - depth) * 3.2);

    let px = x;
    let py = y;

    let influence = 0;

    if (mouse.active) {
      const dx = smoothMouse.x - x;
      const dy = smoothMouse.y - y;
      const dist = Math.hypot(dx, dy);

      influence = Math.exp(-dist * 0.01);

      // dynamic spacing expansion
      const push = influence * 40;
      px = x - dx * push * 0.02;
      py = y - dy * push * 0.02;
    }

    // breathing still applies
    const radialShift = 1 + breath * (0.08 + (1 - depth) * 0.08);
    px *= radialShift;
    py *= radialShift;

    let targetAngle = baseAngle;

    if (mouse.active) {
      const dx = smoothMouse.x - px;
      const dy = smoothMouse.y - py;
      const angleToMouse = Math.atan2(dy, dx) * 180 / Math.PI + 90;
      targetAngle = baseAngle * (1 - influence) + angleToMouse * influence;
    }

    const innerWave = Math.sin(t * 0.75 + phase) * (0.9 + (1 - depth) * 1.6);
    const bend = innerWave + influence * 6;

    const h = tube.h * (1 + breath * 0.04);
    const h2 = h / 2;
    const d = "M 0 " + (-h2).toFixed(2) + " Q " + bend.toFixed(2) + " 0 0 " + (h2).toFixed(2);

    tube.g.setAttribute(
      'transform',
      'translate(' + px.toFixed(2) + ',' + py.toFixed(2) + ') rotate(' + targetAngle.toFixed(2) + ') scale(' + tube.scale.toFixed(3) + ')'
    );
    tube.g.setAttribute('opacity', tube.opacity.toFixed(3));
    tube.path.setAttribute('stroke-width', tube.stroke.toFixed(2));
    tube.path.setAttribute('d', d);
  }

  function tick() {
    if (!running) return;
    t += 0.016;

    if (mouse.active) {
      smoothMouse.x = lerp(smoothMouse.x, mouse.x, 0.08);
      smoothMouse.y = lerp(smoothMouse.y, mouse.y, 0.08);
    } else {
      smoothMouse.x = lerp(smoothMouse.x, 0, 0.03);
      smoothMouse.y = lerp(smoothMouse.y, 0, 0.03);
    }

    const breath = Math.sin(t * 0.34);

    for (let i = 0; i < tubes.length; i++) {
      updateTube(tubes[i], breath);
    }

    if (running) requestAnimationFrame(tick);
  }

  svg.baamEngine = {
    setPaused(paused) {
      const next = !paused;
      if (next === running) return;
      running = next;
      if (running) requestAnimationFrame(tick);
    },
    setPointer(nx, ny, active = true) {
      mouse.x = -320 + Math.max(0, Math.min(1, nx)) * 640;
      mouse.y = -320 + Math.max(0, Math.min(1, ny)) * 640;
      mouse.active = active;
    },
    clearPointer() { mouse.active = false; }
  };
  tick();
})();
